<?php
require_once 'firebase_rest.php';
function saveProviderProfile($uid, $data) { $fields = []; if(isset($data['profile_pic'])) $fields['profile_pic']=['stringValue'=>$data['profile_pic']]; if(isset($data['username'])) $fields['username']=['stringValue'=>$data['username']]; if(isset($data['categories'])) $fields['categories']=['arrayValue'=>['values'=>array_map(fn($c)=>['stringValue'=>$c],$data['categories'])]]; if(isset($data['prices'])) $fields['prices']=['arrayValue'=>['values'=>array_map(fn($p)=>['stringValue'=>$p],$data['prices'])]]; if(isset($data['location'])) $fields['location']=['stringValue'=>$data['location']]; if(isset($data['place_name'])) $fields['place_name']=['stringValue'=>$data['place_name']]; if(isset($data['phone'])) $fields['phone']=['stringValue'=>$data['phone']]; if(isset($data['whatsapp'])) $fields['whatsapp']=['stringValue'=>$data['whatsapp']]; if(isset($data['status'])) $fields['status']=['stringValue'=>$data['status']]; if(isset($data['photos'])) $fields['photos']=['arrayValue'=>['values'=>array_map(fn($url)=>['stringValue'=>$url],$data['photos'])]]; return firebase_update_user($uid,$fields); }
function getProviderProfile($uid) { $user = firebase_get_user($uid); if(!isset($user['fields'])) return []; $f = $user['fields']; return ['profile_pic'=>$f['profile_pic']['stringValue']??'', 'username'=>$f['username']['stringValue']??'', 'categories'=>array_map(fn($v)=>$v['stringValue'],$f['categories']['arrayValue']['values']??[]), 'prices'=>array_map(fn($v)=>$v['stringValue'],$f['prices']['arrayValue']['values']??[]), 'location'=>$f['location']['stringValue']??'', 'place_name'=>$f['place_name']['stringValue']??'', 'phone'=>$f['phone']['stringValue']??'', 'whatsapp'=>$f['whatsapp']['stringValue']??'', 'status'=>$f['status']['stringValue']??'Active', 'photos'=>array_map(fn($v)=>$v['stringValue'],$f['photos']['arrayValue']['values']??[]) ]; }
function getAllApprovedProviders() { $res = firestore_query_collection('users'); $providers = []; foreach($res as $doc) { if(isset($doc['document'])) { $f = $doc['document']['fields']; if($f['account_type']['stringValue']=='service' && $f['approved']['booleanValue']==true && $f['banned']['booleanValue']==false) $providers[]=['uid'=>basename($doc['document']['name']), 'nickname'=>$f['nickname']['stringValue'], 'profile_pic'=>$f['profile_pic']['stringValue']??'assets/images/default-avatar.png', 'location'=>$f['location']['stringValue']??'Unknown', 'status'=>$f['status']['stringValue']??'Active']; } } return $providers; }
?>
